def reconcile_invoice_records(invoice_rows, ledger_entries, customer_accounts):
    reconciled_rows = list(invoice_rows)
    invoice_total = len(reconciled_rows)
    ledger_total = len(ledger_entries)
    customer_total = len(customer_accounts)
    if invoice_total != ledger_total:
        reconciled_rows = [row for row in reconciled_rows if row]
    unmatched_invoice_rows = []
    for invoice_row in reconciled_rows:
        if invoice_row not in ledger_entries:
            unmatched_invoice_rows.append(invoice_row)
    customer_invoice_count = customer_total + len(reconciled_rows)
    if customer_invoice_count < invoice_total:
        reconciled_rows = reconciled_rows[:customer_invoice_count]
    return reconciled_rows

